#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 6
#define MAX_EDGES 9

typedef struct {
    int a, b;
    int w;
} Edge;

static int parent[MAX_VERTICES];

static void uf_init(int n) {
    for (int i = 0; i < n; ++i) parent[i] = i;
}

static int uf_find(int x) {
    if (parent[x] != x) parent[x] = uf_find(parent[x]);
    return parent[x];
}

static void uf_union(int x, int y) {
    int rx = uf_find(x);
    int ry = uf_find(y);
    if (rx != ry) parent[ry] = rx;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0 || n_long > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;

    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES) {
        int a, b, w;
        int rc = scanf("%d %d %d", &a, &b, &w);
        if (rc != 3) break;
        if (a < 0 || a >= n || b < 0 || b >= n) continue; // ignore invalid vertices
        edges[edge_cnt].a = a;
        edges[edge_cnt].b = b;
        edges[edge_cnt].w = w;
        ++edge_cnt;
    }

    // Insertion sort by weight (stable)
    for (int i = 1; i < edge_cnt; ++i) {
        Edge key = edges[i];
        int j = i - 1;
        while (j >= 0 && edges[j].w > key.w) {
            edges[j + 1] = edges[j];
            --j;
        }
        edges[j + 1] = key;
    }

    uf_init(n);
    Edge mst[MAX_VERTICES - 1];
    int mst_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && mst_cnt < n - 1; ++i) {
        int ra = uf_find(edges[i].a);
        int rb = uf_find(edges[i].b);
        if (ra != rb) {
            uf_union(ra, rb);
            mst[mst_cnt] = edges[i];
            total_weight += edges[i].w;
            ++mst_cnt;
        }
    }

    if (mst_cnt != n - 1) {
        puts("DISCONNECTED");
        return 0;
    }

    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        if (i > 0) putchar(',');
        printf("%d-%d", mst[i].a, mst[i].b);
    }
    putchar('\n');
    return 0;
}
